"use client";

import { useEffect, useRef, useState } from "react";
import { motion, useReducedMotion } from "framer-motion";
import { CheckIcon as PhCheck, PlayIcon as PhPlay, StopIcon as PhStop } from "@phosphor-icons/react";

interface Voice {
  id: string;
  name: string;
  accent: string;
}

const PREVIEW_MS = 1800;

function CheckIcon() {
  return <PhCheck size={11} weight="bold" aria-hidden />;
}

function PlayIcon() {
  return <PhPlay size={12} weight="fill" aria-hidden />;
}

function StopIcon() {
  return <PhStop size={10} weight="fill" aria-hidden />;
}

function PreviewButton({
  playing,
  onClick,
  label,
  shouldReduceMotion,
}: {
  playing: boolean;
  onClick: () => void;
  label: string;
  shouldReduceMotion: boolean | null;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      aria-label={playing ? `Stop preview of ${label}` : `Preview ${label}`}
      title={playing ? "Stop preview" : "Preview voice"}
      className={`relative inline-flex h-8 w-8 shrink-0 items-center justify-center rounded-full transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 ${
        playing
          ? "bg-emerald-600 text-white"
          : "bg-black/5 text-slate-500 hover:bg-black/10 hover:text-slate-700 dark:bg-white/10 dark:text-slate-400 dark:hover:bg-white/15 dark:hover:text-slate-200"
      }`}
    >
      {playing && (
        <motion.span
          aria-hidden
          className="absolute inset-[-3px] rounded-full border border-emerald-400/50"
          animate={shouldReduceMotion ? undefined : { scale: [1, 1.3], opacity: [0.6, 0] }}
          transition={{ duration: 1, repeat: Infinity, ease: "easeOut" }}
        />
      )}
      {playing ? <StopIcon /> : <PlayIcon />}
    </button>
  );
}

export function VoiceSelector({
  voices,
  defaultSelectedId,
  onSelect,
}: {
  voices: Voice[];
  defaultSelectedId?: string;
  onSelect?: (id: string) => void;
}) {
  const [selectedId, setSelectedId] = useState(defaultSelectedId ?? voices[0].id);
  const [previewingId, setPreviewingId] = useState<string | null>(null);
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const shouldReduceMotion = useReducedMotion();

  useEffect(() => {
    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, []);

  const togglePreview = (id: string) => {
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    if (previewingId === id) {
      setPreviewingId(null);
      return;
    }
    setPreviewingId(id);
    timeoutRef.current = setTimeout(() => setPreviewingId(null), PREVIEW_MS);
  };

  const select = (id: string) => {
    setSelectedId(id);
    onSelect?.(id);
  };

  const selected = voices.find((v) => v.id === selectedId) ?? voices[0];

  return (
    <div className="w-full max-w-sm rounded-2xl border border-slate-200/70 bg-white/95 p-2 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
      <div className="flex items-center justify-between px-2 pb-1.5 pt-1">
        <p className="text-xs font-semibold uppercase tracking-wide text-slate-400 dark:text-slate-500">Voice</p>
        <p className="text-xs font-medium text-emerald-600 dark:text-emerald-400">{selected.name}</p>
      </div>
      <ul role="radiogroup" aria-label="Select a voice" className="flex flex-col gap-0.5">
        {voices.map((v) => {
          const isSelected = v.id === selectedId;
          const isPlaying = previewingId === v.id;
          return (
            <li key={v.id}>
              <div
                className={`flex items-center gap-2 rounded-lg px-2 py-1.5 transition-colors ${
                  isSelected ? "bg-emerald-500/8 dark:bg-emerald-400/10" : "hover:bg-black/[0.03] dark:hover:bg-white/5"
                }`}
              >
                <button
                  type="button"
                  role="radio"
                  aria-checked={isSelected}
                  onClick={() => select(v.id)}
                  className="flex flex-1 items-center gap-2.5 rounded-md py-0.5 text-left focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600"
                >
                  <span
                    className={`flex h-4 w-4 shrink-0 items-center justify-center rounded-full border-2 transition-colors ${
                      isSelected ? "border-emerald-600 bg-emerald-600 text-white" : "border-slate-300 dark:border-slate-600"
                    }`}
                  >
                    {isSelected && <CheckIcon />}
                  </span>
                  <span className="min-w-0">
                    <span className="block text-sm font-medium text-slate-800 dark:text-slate-100">{v.name}</span>
                    <span className="block text-xs text-slate-400 dark:text-slate-500">{v.accent}</span>
                  </span>
                </button>
                <PreviewButton playing={isPlaying} onClick={() => togglePreview(v.id)} label={v.name} shouldReduceMotion={shouldReduceMotion} />
              </div>
            </li>
          );
        })}
      </ul>
    </div>
  );
}
